from rest_framework import views, permissions, status
from rest_framework.response import Response
from oscar.core.loading import get_model

Basket = get_model('basket', 'Basket')

class MergeSavedBasketView(views.APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        source_basket_id = request.data.get('source_basket_id')
        target_basket_id = request.data.get('target_basket_id')

        # Verify that both the source and target baskets are owned by the requesting user
        try:
            source_basket = Basket.objects.get(pk=source_basket_id, owner=request.user, status=Basket.SAVED)
            target_basket = Basket.objects.get(pk=target_basket_id, owner=request.user)
        except Basket.DoesNotExist:
            return Response({'error': 'Basket not found'}, status=status.HTTP_404_NOT_FOUND)

        target_basket.merge(source_basket)
        return Response({'status': 'Basket merged', 'line_count': target_basket.num_lines})
